import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { FlexModule } from '../flex/flex';
import { FormComponent } from '../form/form';
import { InputNumberComponent } from '../input-number/input-number';
import { InputTextComponent } from '../input-text/input-text';


@Component({
  selector: 'vn-form-sample',
  imports: [FormComponent, ReactiveFormsModule, MatInputModule, MatFormFieldModule, InputNumberComponent, InputTextComponent, FlexModule],
  template: `
  <form vnForm [formGroup]="formGroup" vnFlexRow>  
    <vn-input  formControlName="name" type="text" [required]="true"  [minLength]="3" [maxLength]="30" label="Name" ></vn-input>
    <vn-input  formControlName="price" type="number" [required]="true"  label="Price"> </vn-input>
    <vn-input vnFlexGrow formControlName="age" type="integer" [required]="true"  label="Age" ></vn-input>

      <div vnInput vnFlexCol vnFlexGrow="1" >
      </div>
      <div vnInput vnFlexCol vnFlexGrow="1" >
      </div>

  </form>
  `,
  standalone: true,
})
export class FormSampleComponent implements OnInit {
  formGroup = new FormGroup({
    name: new FormControl(null, Validators.required),
    price: new FormControl(null, Validators.min(0)),
    age: new FormControl(null, Validators.min(18)),
  });

  ngOnInit(): void {
    this.formGroup.valueChanges.subscribe(value => {
      console.log("FormGroup: ", value);
    })

  }



  ctrl(name: string) {
    return this.formGroup.get(name) as FormControl;
  }

}

import { Component, input } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { BaseInput, NumberInputType } from '../input/input';
import { NumberFilterDirective } from '../number-filter/number-filter';

@Component({
  selector: 'vn-input[type=number], vn-input[type=integer]',
  standalone: true,
  imports: [MatFormFieldModule, MatInputModule, ReactiveFormsModule, NumberFilterDirective],
  template: `
  <mat-form-field>
      <mat-label>{{ label() }}</mat-label>
      <input
      type="text"
      matInput
      [formControl]="formControl()"
      [placeholder]="placeholder()"
      [value]="value()"
      [disabled]="disabled()"
      (input)="handleInput($event)"
      (blur)="handleBlur()"
      [min]="min()"
      [max]="max()"
      [maxlength]="16"
      [required]="required()"
      [vnNumberFilter]="type()"     
      [formControl]="formControl()"
      />
      @if (hint()) { <mat-hint>{{ hint() }}</mat-hint> }
      <mat-error>Invalid Input</mat-error>
    </mat-form-field>
  `,
  styleUrls: ['../input/input.scss'],
})
export class InputNumberComponent extends BaseInput<number, NumberInputType> {
  min = input<number>(Number.MIN_SAFE_INTEGER)
  max = input<number>(Number.MAX_SAFE_INTEGER)

  protected override convertToValue(value: string): any {

    if (value === null || value === undefined || value === '') {
      return null
    }

    const parsedValue = this.type() === 'integer'
      ? parseInt(value, 10)
      : parseFloat(value);

    return isNaN(parsedValue) ? null : parsedValue;

  }
}

